import { useEffect, useState } from "react";

import Registration from "./Registration";
import Verification from "./Verification";
import Confirmation from "./Confirmation";
import Home from "./Home";
import PostItem from "./PostItem";
import ItemDetails from "./ItemDetails";
import Chat from "./Chat";

import {
  collection,
    addDoc,
      onSnapshot,
        query,
          orderBy,
            serverTimestamp,
            } from "firebase/firestore";

            import { db } from "./firebase";

            type Item = {
              id?: string;
                title: string;
                  category: string;
                    price: string;
                      location: string;
                        description: string;
                          image: string;
                          };

                          export default function App() {
                            const [step, setStep] = useState("registration");

                              const [phone, setPhone] = useState("");

                                const [items, setItems] = useState<Item[]>([]);

                                  const [selectedItem, setSelectedItem] =
                                      useState<Item | null>(null);

                                        // LOAD ITEMS FROM FIRESTORE
                                          useEffect(() => {
                                              const itemsRef = collection(db, "items");

                                                  const itemsQuery = query(
                                                        itemsRef,
                                                              orderBy("createdAt", "desc")
                                                                  );

                                                                      const unsubscribe = onSnapshot(
                                                                            itemsQuery,
                                                                                  (snapshot) => {
                                                                                          const loadedItems: Item[] = snapshot.docs.map(
                                                                                                    (doc) => ({
                                                                                                                id: doc.id,
                                                                                                                            ...(doc.data() as Omit<Item, "id">),
                                                                                                                                      })
                                                                                                                                              );

                                                                                                                                                      setItems(loadedItems);
                                                                                                                                                            },
                                                                                                                                                                  (error) => {
                                                                                                                                                                          console.error(
                                                                                                                                                                                    "Error loading items from Firestore:",
                                                                                                                                                                                              error
                                                                                                                                                                                                      );
                                                                                                                                                                                                            }
                                                                                                                                                                                                                );

                                                                                                                                                                                                                    return () => unsubscribe();
                                                                                                                                                                                                                      }, []);

                                                                                                                                                                                                                        // REGISTRATION
                                                                                                                                                                                                                          const handleRegistration = (userPhone: string) => {
                                                                                                                                                                                                                              setPhone(userPhone);
                                                                                                                                                                                                                                  setStep("verification");
                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                      // VERIFICATION
                                                                                                                                                                                                                                        const handleVerified = () => {
                                                                                                                                                                                                                                            setStep("confirmation");
                                                                                                                                                                                                                                              };

                                                                                                                                                                                                                                                // CONFIRMATION
                                                                                                                                                                                                                                                  const handleContinue = () => {
                                                                                                                                                                                                                                                      setStep("home");
                                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                                          // OPEN POST ITEM
                                                                                                                                                                                                                                                            const handlePostItem = () => {
                                                                                                                                                                                                                                                                setStep("postItem");
                                                                                                                                                                                                                                                                  };

                                                                                                                                                                                                                                                                    // SAVE NEW ITEM TO FIRESTORE
                                                                                                                                                                                                                                                                      const handleNewItem = async (item: Item) => {
                                                                                                                                                                                                                                                                          try {
                                                                                                                                                                                                                                                                                await addDoc(collection(db, "items"), {
                                                                                                                                                                                                                                                                                        title: item.title,
                                                                                                                                                                                                                                                                                                category: item.category,
                                                                                                                                                                                                                                                                                                        price: item.price,
                                                                                                                                                                                                                                                                                                                location: item.location,
                                                                                                                                                                                                                                                                                                                        description: item.description,
                                                                                                                                                                                                                                                                                                                                image: item.image,
                                                                                                                                                                                                                                                                                                                                        createdAt: serverTimestamp(),
                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                    console.log(
                                                                                                                                                                                                                                                                                                                                                            "✅ Item saved successfully to Firestore"
                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                      } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                            console.error(
                                                                                                                                                                                                                                                                                                                                                                                    "❌ Error saving item:",
                                                                                                                                                                                                                                                                                                                                                                                            error
                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                        throw error;
                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                              };

                                                                                                                                                                                                                                                                                                                                                                                                                // SELECT ITEM
                                                                                                                                                                                                                                                                                                                                                                                                                  const handleSelectItem = (item: Item) => {
                                                                                                                                                                                                                                                                                                                                                                                                                      setSelectedItem(item);
                                                                                                                                                                                                                                                                                                                                                                                                                          setStep("itemDetails");
                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                              // BACK FROM DETAILS
                                                                                                                                                                                                                                                                                                                                                                                                                                const handleBackFromDetails = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                    setSelectedItem(null);
                                                                                                                                                                                                                                                                                                                                                                                                                                        setStep("home");
                                                                                                                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                                                                                                                            // OPEN CHAT
                                                                                                                                                                                                                                                                                                                                                                                                                                              const handleChat = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                  setStep("chat");
                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                      // BACK FROM CHAT
                                                                                                                                                                                                                                                                                                                                                                                                                                                        const handleBackFromChat = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                            setStep("home");
                                                                                                                                                                                                                                                                                                                                                                                                                                                              };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                // REGISTRATION
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (step === "registration") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <Registration
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onRegistered={handleRegistration}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // VERIFICATION
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (step === "verification") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Verification
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      phone={phone}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              onVerified={handleVerified}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // CONFIRMATION
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (step === "confirmation") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Confirmation
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                onContinue={handleContinue}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // POST ITEM
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (step === "postItem") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <PostItem
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onBack={() => setStep("home")}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onPost={handleNewItem}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ITEM DETAILS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (step === "itemDetails" && selectedItem) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <ItemDetails
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            item={selectedItem}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    onBack={handleBackFromDetails}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            onContactSeller={handleChat}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // CHAT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (step === "chat") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Chat
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                itemTitle={selectedItem?.title ?? ""}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  onBack={handleBackFromChat}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  />                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // HOME
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Home
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  items={items}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onPostItem={handlePostItem}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          onViewItem={handleSelectItem}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }